"timeLimit": 15}]'::jsonb, true, NOW()),
('95c2a4ee-7e06-4073-82eb-7f876749472a', '21feff02-016d-46e2-bb9d-c27495133b1b', '134. óra: Arányosság, százalék, szöveges feladatok', 'Év végi ismétlés: egyenes arányosság, százalékszámítás, nyitott mondatok.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "91c0cbcc-d326-45ed-8452-1dba86cac9c6", "text": "Ossz el 500 Ft-ot 2 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "c7fafb81-f368-4d70-a04c-86ec9617fceb", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 7 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2800"}, {"id": "2e5e7099-f93e-4b23-ac3b-d5bbb08ab46d", "text": "Mennyi 4000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "800"}, {"id": "fea61ddc-6b31-4e4a-bd4f-4d18405da0b9", "text": "Melyik szám teszi igazzá: 3 * x + 5 = 26? (21/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "ca9999fc-91ff-4351-95cc-950ce0406ee2", "text": "Gondoltam egy számot, elosztottam 4-gyel, hozzáadtam 6-ot, 11-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "839b3367-4746-4647-9699-aa0e5b1c1418", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "c274f2e9-2f55-4b65-88db-65553f175c0b", "text": "Igaz", "isCorrect": true}, {"id": "cf70a7b7-0145-4ae5-b1b1-fcefe888fa40", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d53e3597-176e-40ca-8788-d34a34fa2eb4", "text": "Hány százalék felel meg a 4/5 törtszám teljes értékének?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}]'::jsonb, true, NOW()),
('6ae3db5b-7b1a-4613-9906-ea98900c6aea', '21feff02-016d-46e2-bb9d-c27495133b1b', '135. óra: A hosszúság, a kerület, a terület és a térfogat fogalmával kapcsolatos feladatok', 'Év végi ismétlés: mérések, kerület, terület, felszín, térfogat.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "8d2b5799-7312-4ddb-ad18-7b7cc367de7e", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "8e40edc2-01a3-4758-874d-2bddf7a140b3", "text": "Mennyi a 6 cm és 5 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "7b9c74d5-e96d-4a70-a72b-0f9428ca7c0f", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "c97fabb5-bf9a-4571-81be-0cb0d3cd4821", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "be9aa0b1-f64e-4c37-9369-cf6201e3838b", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "a027e898-2d97-430e-91af-ab797e562842", "text": "Igaz", "isCorrect": true}, {"id": "8303eb39-681c-4086-b957-7ec5faf81d25", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9ace1e34-36d8-4cea-8851-75240ca23b0f", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "f2656639-e988-43fa-bd83-1c293ad84932", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]'::jsonb, true, NOW()),
('422930c4-f0bb-4aa7-a2a1-fd65b7640766', '21feff02-016d-46e2-bb9d-c27495133b1b', '136. óra: Az éves munka értékelése', 'Az 6. osztályos matematika törzsanyag sikeres teljesítésének záró értékelése.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "e18c390c-699e-456d-8de1-a1a653553de7", "text": "Mely főbb témaköröket dolgoztuk fel a 6. osztályos matematika tananyagban?", "type": "multiple-choice", "options": [{"id": "45e1e82b-9ee6-4679-9cb9-5ca943499643", "text": "Egész számok, oszthatóság, törtek, geometria, arány és százalék, kerület-terület-felszín-térfogat, statisztika, pénzügyek", "isCorrect": true}, {"id": "2596627b-3a1e-4a34-9692-03bc48f6aae2", "text": "Kizárólag geometria", "isCorrect": false}, {"id": "b0c61a5f-2baf-4810-966f-36b8b7874fab", "text": "Kizárólag rajzolás", "isCorrect": false}, {"id": "f9a25b16-1596-4c06-9a3a-ec8fb7e33128", "text": "Csak az 1. osztályos ismétlés", "isCorrect": false}], "timeLimit": 15}, {"id": "a52f8abd-b4b1-4f8e-80ad-e01c467ec956", "text": "A szorgalmas felkészülés és a rendszerezett gyakorlás a matematikai tudás alapja.", "type": "true-false", "options": [{"id": "f736061f-d5c8-4c23-88e6-fabcf05ad8aa", "text": "Igaz", "isCorrect": true}, {"id": "64cfb227-d414-4a99-a041-efa359587eac", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "730be1f2-a0a2-4a2d-bc4f-981d6ec4c8c6", "text": "Hány órából állt a 6. osztályos teljes matematika tananyag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "136"}, {"id": "a2dfcef5-9d34-4b62-acae-ea146ca68b3d", "text": "A megszerzett matematikai tudás segít a mindennapi pénzügyekben és a döntéshozatalban.", "type": "true-false", "options": [{"id": "c0736d80-e781-470e-b66e-362a75529ed9", "text": "Igaz", "isCorrect": true}, {"id": "64b5733d-b94a-4f5e-8eb5-d7abb3d3a56c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5c5f8021-cb8d-4d91-949c-a1f6571e8979", "text": "Gratulálunk a 6. osztályos matematika tananyag sikeres teljesítéséhez!", "type": "true-false", "options": [{"id": "64bf8f83-c63e-40b0-8ea6-4953b00e8776", "text": "Igaz", "isCorrect": true}, {"id": "715e35dc-02ac-4c47-baf7-898cb2fba90c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "66465d97-5f2a-470c-b74f-5d52cf6c954d", "text": "A 7. osztályban az itt megszerzett alapokra (pl. oszthatóság, törtek, százalék, geometria) építünk tovább.", "type": "true-false", "options": [{"id": "34f370ee-f48b-4205-9985-75aaef5ac906", "text": "Igaz", "isCorrect": true}, {"id": "9a884d88-5177-4bbc-9ab2-158f89000568", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "70538047-686c-4c99-b373-0b411c982c83", "text": "Melyik volt a kedvenc témaköröd ebben a tanévben?", "type": "multiple-choice", "options": [{"id": "9d1f3bd4-83a0-4d36-a99a-8bff3defdc53", "text": "Mindegyik témakör hasznos és érdekes volt!", "isCorrect": true}, {"id": "40a8414c-7047-4282-b41d-d44c9e0208db", "text": "Egész számok és oszthatóság", "isCorrect": false}, {"id": "626d7c68-d6f8-46c3-a364-5d6ccbc83b51", "text": "Geometria és tengelyes tükrözés", "isCorrect": false}, {"id": "faafc8bd-3582-42fb-ba6f-acf767f2d8aa", "text": "Arányosság és százalékszámítás", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());